    "commentary": {
      "quotes": [
        "제10항~제12항에서는 국어의 두음 법칙을 규정하였다. 두음 법칙은 단어의 첫머리 에 특정한 소리가 출현하지 못하는 현상을 말한다. ‘녀, 뇨, 뉴, 니’를 포함하는 한자어음절이 단어 첫머리에 올 때는 ‘ㄴ’이 나타나지 못하여 ‘여, 요, 유, 이’의 형태로 실현 되는데, 이 조항에서는 이러한 두음 법칙의 내용을 규정하였다.",
        "연도(年度) 열반( 涅槃) 요도( 尿道) 이승(尼僧) 이공( 泥工) 익사( 溺死) 그런데 여기에는 예외가 있다. 한자어 음절이 ‘녀, 뇨, 뉴, 니’를 포함하고 있더라도 의존 명사에는 두음 법칙이 적용되지 않는다. 이는 의존 명사는 독립적으로 쓰이기보다는 그 앞의 말과 연결되어 하나의 단위를 구성하기 때문이다.",
        "즉 ‘냥, 냥쭝, 년’ 등과 같은 의존 명사는 한글 맞춤법 제42항에 따라 앞말과 띄어 쓰지만 언제나 의존하는 대상과 하나의 단위로 쓰인다. 이러한 이유로 이 말들은 독립 된 단어로 잘 인식되지 않고, 그 결과 단어의 첫머리에도 ‘연도, 열반’ 등과 달리 두음",
        "법칙이 적용되지 않는다. 따라서 소리 나는 대로 적는다.",
        "십 년 금 한 냥 은 두 냥쭝 따라서 ‘年’, ‘年度’처럼 의존 명사로 쓰이기도 하고 명사로 쓰이기도 하는 한자어의 경우에는 두음 법칙의 적용에서 차이가 난다. ‘년, 년도’가 의존 명사라면 ‘연, 연도’는 명사이다.",
        "연 강수량(명사) 일 년(의존 명사) 생산 연도(명사) 2018 년도(의존 명사) [붙임 1] 단어의 첫머리가 아닌 경우에는 두음 법칙이 적용되지 않으므로 본음대로 적는 것이다.",
        "소녀(少女) 만 년(晩年) 배 뇨(排尿) 비구니(比丘尼) 운 니(雲泥) 탐 닉(耽溺) [붙임 2] ‘신-여성, 구-여성, 공-염불’은 이미 두음 법칙이 적용된 자립적인 명사 ‘여성, 염불’에 ‘신-, 구-, 공-’이 결합한 구조이므로 ‘신여성, 구여성, 공염불’로 적는다. ‘접두사처럼 쓰이는 한자’라고 한 것은 ‘신(新), 구(舊)’와 같은 한자를 접두사로만 단정하기 어렵다는 점을 밝힌 것이다. 실제로 ‘구(舊)’는 ‘구 시민 회관’과 같은 구성에 서는 관형사로도 쓰인다. ‘남존-여비, 남부-여대’ 등은 엄밀히 말하면 합성어는 아니 지만, ‘남존’, ‘여비’, ‘남부’, ‘여대’ 등이 마치 단어와 같이 인식되어 두음 법칙이 적용 된 형태로 굳어져 쓰이고 있는 것이다. 한편 ‘신년도, 구년도’ 등은 발음이 [신년도], [구ː년도]이며 ‘신년-도, 구년-도’로 분석되는 구조이므로 이 규정이 적용되지 않는다. [붙임 3] 둘 이상의 단어로 이루어진 고유 명사를 붙여 쓰는 경우에도, 결합된 각 단어를 두음 법칙에 따라 적는다. 따라서 ‘한국 여자 농구 연맹’을 붙여서 쓰면 ‘한국여 자농구연맹’이 된다."
      ]
    }
