        "단어의 첫머리가 아닌 경우에는 두음 법칙이 적용되지 않는 것이 원칙이다. 다만, 모음이나 ‘ㄴ’ 받침 뒤에 결합되는 ‘렬(列, 烈, 裂, 劣), 률(律, 率, 栗, 慄)’은 ‘나열[나 열], 비율[비ː율], 선열[서녈], 운율[우ː뉼]’ 등에서와 같이 [열], [율]로 소리 나므로 소 리대로 ‘열, 율’로 적는다.",
        "나열(羅列)비 열 ( 卑劣)균 열 ( 龜裂) 분열( 分列) 서열(序列)우 열 ( 優劣)분 열 ( 分裂) 선열( 先烈) 의열(義烈)치 열 ( 熾烈)전 열 ( 前列) 천열( 賤劣) 규율(規律)비 율 ( 比率)백 분 율 ( 百分率) 선율( 旋律) 외율(煨栗)이 율 ( 利率)운 율 ( 韻律) 전율( 戰慄) 자율(自律)조 율 ( 棗栗)환 율 ( 換率) ‘率’은 모음이나 ‘ㄴ’ 받침 뒤에서는 ‘이자율(利子率)[이ː자율], 회전율(回轉率)[회전 뉼/훼전뉼]’처럼 ‘율’로 적고 그 외의 받침 뒤에서는 ‘능률(能率)[능뉼], 합격률(合格 率)[합꼉뉼]’처럼 ‘률’로 적는다. 외래어에서도 동일하게 모음이나 ‘ㄴ’ 받침 뒤에서는 ‘율’로 적고 그 외의 받침 뒤에서는 ‘률’로 적는다.",
        "서비스-율(service率) 시엔-율(CN 率) 슛-률(shoot率)영 - 률(Young率) [붙임 2] 널리 알려진 역사적인 인물 성명의 발음이 ‘申砬[실립], 崔麟[최린]’처럼 굳 어져 있는 경우에는 ‘신립, 최린’과 같이 적을 수 있다. “표준국어대사전”에는 이러한 점을 반영하여 ‘신입’과 ‘신립’, ‘최인’과 ‘최린’을 동의어로 처리하였다. 현재 “표준국어 대사전”에서 이와 같이 처리한 역사적 인물은 다음과 같다.",
        "신입/신립(申砬) 최인/최린( 崔麟) 채윤/채륜( 蔡倫) 하윤/하륜(河崙) 김입/김립( 金笠) [붙임 3] 둘 이상의 단어로 이루어진 말이 줄어들어 하나의 단위로 인식될 때에는 두음 법칙이 적용되지 않아서 소리 나는 대로 적는다. 이 경우 뒤의 한자는 하나의 단 어가 아니기 때문에 두음 법칙이 적용되지 않는다. 예를 들어 ‘국제 연합’은 ‘국련’으로 줄여서 쓸 수 있다. ‘국제’의 ‘국’과 ‘연합’의 ‘연’을 따서 만든 말인데, ‘연’ 자체는 하나 의 단어가 아니기 때문에 두음 법칙이 적용되지 않아서 ‘국련’으로 쓰는 것이다. ‘한국 시각 장애인 연합회’를 ‘한시련’으로 쓰는 것도 같은 이유에서이다. [붙임 4] 한글 맞춤법 제10항의 규정과 마찬가지로, 독립성이 있는 단어에 ‘접두사 처럼 쓰이는 한자’가 결합하여 된 단어에는 두음 법칙을 적용한다. 또한 두 단어가 결 합하여 된 합성어나 이에 준하는 구조도 두음 법칙이 적용된 형태로 적는다.",
        "몰-이해(沒理解) 과-인산( 過燐酸)가 - 영 수 ( 假領收) 등-용문(登龍門) 불-이행( 不履行)사 - 육 신 ( 死六臣) 생-육신(生六臣) 선-이자( 先利子)무 실 - 역 행 ( 務實力行) 청-요리(淸料理)수 학 - 여 행 ( 修學旅行)낙 화 - 유 수 (落花流水) 한편 고유어나 외래어 뒤에 결합한 한자어는 독립적인 한 단어로 인식이 되기 때문 에 두음 법칙이 적용된다.",
        "가시-연(蓮)구 름 - 양 ( 量) 허파숨-양(量)먹 이 - 양 ( 量) 벡터(vector)-양(量)에 너 지 ( e n e r g y ) - 양 (量) ‘量’이 고유어 ‘구름’과 결합하면 ‘구름양’이 되는 것은 ‘양’이 하나의 독립적인 단어로 인식되기 때문이다. 한자와 결합하면 ‘운량(雲量)’처럼 ‘량’으로 적는다. ‘이슬양’과 ‘노량(露量)’도 마찬가지 이유로 각각 ‘양’과 ‘량’으로 적는다. [붙임 5] 수를 나타내는 ‘육’은 ‘십육(十六), 육육삼십육(6×6=36)’처럼 독립적으로 쓰이는 경우에는 두음 법칙에 따라 적는다. 그렇지만 ‘오륙도(五六島), 사륙판(四六 判)’ 등은 ‘오’와 ‘육’, ‘사’와 ‘육’이 독립적인 단어로 나누어지는 구조가 아니므로 본음",
