    "commentary": {
      "quotes": [
        "한글 맞춤법 제1항의 소리대로 적되 어법에 맞도록 한다는 원칙 가운데 ‘어법’에 해 당하는 원칙을 제시하고 있다. 실질 형태소인 체언과 형식 형태소인 조사를 분리하여 적음으로써 체언과 조사의 형태를 고정한다. 예를 들어 ‘값[價]’에 다양한 조사가 결합 한 형태를 소리 나는 대로 적으면 다음과 같다.",
        "갑씨 갑쓸 갑또 감만 그런데 이렇게 적으면 하나의 형태가 여러 가지로 표기되어 실질 형태소의 본모양 과 형식 형태소의 본모양이 무엇인지, 둘의 경계가 어디인지를 알아보기가 어렵다. 이 와 달리 실질 형태소와 형식 형태소를 구분해서 적으면 의미와 기능을 나타내는 부분 의 모양이 일관되게 고정되어서 뜻을 파악하기가 쉽고 독서의 능률도 향상된다.",
        "값이 값을 값도 값만 ‘값이’는 ‘갑씨’와 비교할 때 실질 형태소 ‘값’과 형식 형태소 ‘이’가 분리됨으로써 의 미를 파악하기가 쉽다는 장점이 있다. 이 조항에서 본모양을 밝혀 적는다는 것은 ‘값, 이’, ‘값, 을’의 각 형태를 나누어 적는 것이라고 할 수 있다. 따라서 ‘갑씨, 갑쓸’, ‘갑 시, 갑슬’이 아니라 ‘값이, 값을’로 적는다. 한글 맞춤법 제1항의 ‘어법에 맞도록 한다’ 에는 이처럼 체언과 조사를 구분하여 적음으로써 의미 파악을 쉽게 하여 독서의 능률을 높인다는 의미가 포함되어 있다. 체언과 조사는 다음과 같이 다양하게 결합할 수 있는데, 항상 체언과 조사의 본모양을 밝혀서 적는다.",
        "꽃이 + 부엌 을 앞에 흙의 값으 로 밭이 다"
      ]
    }
