    "commentary": {
      "quotes": [
        "체언에 조사가 결합할 때와 마찬가지로 실질 형태소인 어간과 형식 형태소인 어미 의 형태를 고정해서 일관되게 적는다. 예를 들어 어간 형태소 ‘읽-’에 다양한 어미가 결합한 형태를 소리 나는 대로 적으면 다음과 같다. [ .",
        "( [ .) ㄱㄴ .",
        ". [ .) ㄱㄴ , .",
        "일꼬 익찌 잉는 일그니 그런데 이렇게 적으면 형태소의 형태가 여러 가지로 표기되어서 실질 형태소의 본 모양과 형식 형태소의 본모양이 무엇인지, 둘의 경계가 어디인지를 알아보기가 어렵다. 이와 달리 실질 형태소와 형식 형태소가 구분되도록 하면 의미와 기능을 나타내는 부분의 모양이 일관되게 고정되어서 뜻을 파악하기가 쉽고 독서의 능률도 향상된다.",
        "읽고 읽지 읽는 읽으니 ‘읽고’는 ‘일꼬’와 비교할 때 실질 형태소 ‘읽-’과 형식 형태소 ‘-고’가 구분됨으로써 의미를 파악하기가 쉽다는 장점이 있다. 이 조항에서 본모양을 밝혀 적는다는 것은 ‘일 꼬, 익찌, 일거, 일그니’가 아닌, ‘읽고, 읽지, 읽어, 읽으니’로 어간과 어미의 각 형태를 밝혀 적는 것이라고 할 수 있다. 한글 맞춤법 제1항의 ‘어법에 맞도록 한다’에는 이 처럼 어간과 어미를 구분하여 적음으로써 의미 파악을 쉽게 하고 독서의 능률을 높인다는 의미도 포함되어 있다. 어간과 어미는 다음과 같이 다양하게 결합할 수 있는데, 항상 어간과 어미의 본모양을 밝혀서 적는다.",
        "꺾- -어 + 잊- -으니 덮- -도록 핥- -는다",
        "붙- -느냐 먹- -거든 [붙임 1] ‘앞말의 본뜻이 유지되고 있는 것’은 두 개의 용언이 결합하여 하나의 단어 가 될 때 앞말의 의미가 유지되는 경우를 말한다. 이 경우에는 앞말의 본모양을 밝혀 적는다. 이와 달리 ‘본뜻에서 멀어진 것’은 단독으로 쓰일 때의 의미가 유지되지 않고다른 의미로 변화했다는 뜻으로, 이 경우에는 소리 나는 대로 적는다.",
        "늘어나다(늘다) 늘어지다(늘다) 돌아가다(돌다) 들어가다(들다) 떨어지다(떨다) 벌어지다(벌다) 엎어지다(엎다) 틀어지다(틀다) 흩어지다(흩다) 위의 예들은 앞말의 본뜻이 유지되고 있어서 본모양대로 적은 것이다. ‘늘어나다’, ‘돌아가다’에는 ‘늘다’와 ‘돌다’의 의미가 유지되고 있으므로 ‘느러나다’, ‘도라가다’로 적지 않는다. 다만 원래의 의미가 유지되고 있는지를 명백하게 판단하기 쉽지 않은 경 우가 있다. ‘넘어지다’, ‘접어들다’는 ‘넘다’와 ‘접다’의 의미가 유지되고 있는지 명확하 지는 않지만 둘을 연관 지어 온 전통에 따라 ‘넘어지다’, ‘접어들다’로 적는다.",
        "이와 달리 앞말이 본뜻에서 멀어진 경우에는 본모양대로 적지 않는다. 예를 들어 ‘드러나다’, ‘사라지다’, ‘쓰러지다’는 ‘들다’, ‘살다’, ‘쓸다’의 본뜻이 유지되고 있다고 하기 어렵다. ‘쓸다’는 ‘(빗자루가) 잘 쓸어지다’와는 관련이 있지만 ‘(나무가) 쓰러지다’ 와는 의미상 거리가 멀다. 이처럼 본뜻에서 멀어진 예로는 다음과 같은 것들이 있다.",
        "나타나다 바라지다[ 坼] 배라먹다[ 乞食] 부서지다[ 碎] 불거지다[凸] 부러지다[ 折] 자빠지다[ 沛] [붙임 2, 3] “이것은 책이오.”, “이것은 책이요, 저것은 붓이다.”의 ‘이오’, ‘이요’는 모두 [이요]로 소리 나더라도 종결 어미로 쓰일 때는 ‘오’, 연결 어미로 쓰일 때는 ‘요’ 로 적는다. “이것은 책이오.”는 “같이 가오.”, “꽃이 예쁘오.”, “앉으시오.”처럼 어간에 ‘-오’가 공통적으로 결합한 것이므로 ‘이-’ 뒤에 쓰여 ‘요’로 소리가 난다고 해도 ‘요’로 적지 않고 ‘오’로 적는 것이다. 그렇지만 “이것은 책이요, 저것은 붓이다.”의 ‘이요’는 역사적으로 ‘이고’에서 ‘ㄱ’이 약화되면서 형성된 것으로 ‘오’가 분리되어 쓰이는 다른 경우가 없이 이미 ‘요’로 변화했으므로 소리 나는 대로 ‘요’로 적는다."
      ]
    }
