        "본뜻이 유지됨 본뜻에서 멀어짐 걸다 목걸이(목에 거는 물건) 목거리(목이 아픈 병) 놀다 놀음(놀이) 노름(돈내기) 다만 불규칙 활용을 하는 어간에 ‘-이, -음’이 결합하여 소리가 변한 경우에는 변한 대로 적는다. 예를 들어 ‘쉽-’에 ‘-이’가 결합한 말은 [쉬이]로 발음되고, ‘서럽-’에 ‘-음’이 결합한 말은 [서ː러움]으로 발음된다. 그런데 이것을 원형을 밝혀 ‘쉽이, 서럽음’ 으로 적으면 [쉬비, 서ː러븜]으로 읽혀서 표준어와는 달리 발음된다. 따라서 이러한 말은 소리대로 ‘쉬이, 서러움’으로 적는다. [붙임] ‘-이’, ‘-음’이 아닌 모음으로 시작하는 접미사가 결합한 경우에는 어간의 원 형을 밝혀 적지 않는다. 이러한 접미사는 결합하는 어간이 제약되어 있고 더 이상 새 로운 말도 만들어 내지 못한다.",
