        "첫째, 이 항에서 규정하고 있듯이 ‘-하다’가 붙는 어근에 ‘-이/-히’가 붙어 부사가 형성되는 경우이다. ‘-하다’가 붙는 어근이란 ‘급하다, 꾸준하다, 깨끗하다’에서 ‘-하다’와 결합하는 ‘급, 꾸준, 깨끗’을 말한다. 이처럼 ‘-하다’와 결합하는 어근은 부사 파 생 접미사 ‘-이/-히’와 결합하여 부사를 형성할 때 어근의 본뜻이 일관되게 유지된다.",
        "또한 이러한 ‘-이’나 ‘-히’는 매우 다양한 어근과 결합하여 부사를 만든다. 따라서 이 러한 경우에는 어근의 형태를 밝혀 적는 것이 합리적이다.",
        "꾸준 꾸준-하다 (한결같이 부지런하고 끈기가 있다) 꾸준-히(한결같이 부지런하고 끈기가 있는 태도로) 버젓 버젓-하다 (남의 시선을 의식하여 조심하거나 굽히는 데가 없다) 버젓-이(남의 시선을 의식하여 조심하거나 굽히는 데가 없이) 다만, ‘-하다’가 붙지 않아서 어근과 접미사를 분리하기 어려울 때에는 어근의 원형을 밝히지 않고 소리 나는 대로 적는다. 예를 들어 [반드시]는 ‘반듯하다’의 어근 ‘반듯’ 의 본뜻이 유지될 때와 유지되지 않을 때를 구별할 수 있다.",
        "반듯 반듯-하다 (생김새가 아담하고 말끔하다) 반듯-이(생김새가 아담하고 말끔히) 󰃚 소나무가 반듯이 서 있다.",
