        "이는 ‘높이, 많이, 밝히’ 등에는 적용되지 않는다. 이들은 ‘높-, 많-, 밝-’ 등의 어 근이 분명히 드러나므로, ‘높이, 많이, 밝히’와 같이 어근의 원형을 밝혀 적는다.(한글 맞춤법 제19항) 둘째, 부사에 ‘-이’가 붙어 부사가 되는 경우이다. ‘-이’가 결합해도 원래의 부사와 의미와 기능이 다르지 않으므로 관련성이 드러나도록 원형을 밝혀 적는다.",
