/**
 * @param {string} anchor
 * @returns {HangulOrthographyArticle | undefined}
 */
export function findHangulOrthographyArticle(anchor) {
  return HANGUL_ORTHOGRAPHY_ARTICLES.find((a) => a.anchor === anchor);
}

/**
 * @param {number} number
 * @returns {string}
 */
export function hangulOrthographyAnchor(number) {
  return `art-${Number(number)}`;
}

/**
 * 국립국어원 고시 목차와 같이 본문 → 장 → 절 → 항으로 묶는다.
 * @param {HangulOrthographyArticle[]} [articles]
 * @returns {{ chapter: string, sections: { section: string, articles: HangulOrthographyArticle[] }[] }[]}
 */
export function groupHangulOrthographyTree(articles = HANGUL_ORTHOGRAPHY_ARTICLES) {
  /** @type {{ chapter: string, sections: { section: string, articles: HangulOrthographyArticle[] }[] }[]} */
  const groups = [];
  for (const art of articles) {
    let chapter = groups[groups.length - 1];
    if (!chapter || chapter.chapter !== art.chapter) {
      chapter = { chapter: art.chapter, sections: [] };
      groups.push(chapter);
    }
    const sectionKey = art.section || '';
    let section = chapter.sections[chapter.sections.length - 1];
    if (!section || section.section !== sectionKey) {
      section = { section: sectionKey, articles: [] };
      chapter.sections.push(section);
    }
    section.articles.push(art);
  }
  return groups;
}

/**
 * @param {HangulOrthographyArticle} art
 * @returns {string[]}
 */
function articleSearchCorpus(art) {
  return [
    art.text,
    ...(art.ruleExamples ?? []),
    art.proviso ?? '',
    ...(art.provisoExamples ?? []),
    ...(art.commentary?.quotes ?? []),
    ...(art.commentary?.examples ?? []),
    `제${art.number}항`,
    art.chapter,
    art.section,
  ].filter(Boolean);
}

/**
 * @param {string} value
 */
function foldSearchText(value) {
  return String(value).replace(/\s+/g, ' ').trim().toLowerCase();
}

/**
 * @param {string} text
 * @param {string} query
 * @param {number} [radius]
 */
function searchSnippet(text, query, radius = 42) {
  const folded = foldSearchText(text);
  const q = foldSearchText(query);
  const at = folded.indexOf(q);
  if (at < 0) return foldSearchText(text).slice(0, radius * 2);
  const start = Math.max(0, at - radius);
  const end = Math.min(folded.length, at + q.length + radius);
  return `${start > 0 ? '…' : ''}${folded.slice(start, end)}${end < folded.length ? '…' : ''}`;
}

/**
 * 이 페이지(제1–57항 조문·용례·다만·해설)만 찾는다. 앱의 다른 화면은 보지 않는다.
 * @param {string} query
 * @param {HangulOrthographyArticle[]} [articles]
 * @returns {{ article: HangulOrthographyArticle, snippet: string }[]}
 */
export function searchHangulOrthographyArticles(query, articles = HANGUL_ORTHOGRAPHY_ARTICLES) {
  const q = foldSearchText(query);
  if (!q) return [];
  const numbered = q.match(/^제?\s*(\d+)\s*항?$/);
  const wantNumber = numbered ? Number(numbered[1]) : NaN;
  /** @type {{ article: HangulOrthographyArticle, snippet: string }[]} */
  const hits = [];
  for (const art of articles) {
    if (Number.isFinite(wantNumber) && art.number === wantNumber) {
      hits.push({ article: art, snippet: art.text });
      continue;
    }
    const field = articleSearchCorpus(art).find((row) => foldSearchText(row).includes(q));
    if (field) hits.push({ article: art, snippet: searchSnippet(field, q) });
  }
  return hits;
}
